import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { canonicalDigest } from '@studio/package-kit';
import { parseStrictJson } from '@studio/spec';
import type { IndexRef, Principal } from '@studio/rag-core';
import { RunnerError } from '../errors.js';
import { storagePath } from './store.js';
import { RUN_RAG_LIMITS } from './run-contract.js';

interface Operation { requestHash: string; status: string; result: unknown }
const APPLICATION_ID = 0x53525247;

/** Durable intent/budget journal. The installation identity is generated by the service, never read from a workflow. */
export class RunRagLedger {
  readonly #db: DatabaseSync;
  readonly #installation: string;
  #closed = false;
  constructor(filename: string) {
    this.#db = new DatabaseSync(storagePath(filename), { allowExtension: false });
    try {
      const version = Number(this.#db.prepare('PRAGMA user_version').get()!.user_version);
      const application = Number(this.#db.prepare('PRAGMA application_id').get()!.application_id);
      const tables = this.#db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all().map(row => row.name);
      if (version !== 0 && version !== 1 || version === 0 && (application !== 0 || tables.length) || version === 1 && (application !== APPLICATION_ID || tables.join(',') !== 'identity,operations')) throw new RunnerError('RAG_LEDGER_VERSION', '검색 실행 기록의 버전·형식을 지원하지 않습니다.');
      this.#db.exec('PRAGMA trusted_schema=OFF; PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA busy_timeout=5000; PRAGMA max_page_count=8192;');
      if (version === 0) this.transaction(() => {
        this.#db.exec(`CREATE TABLE identity(id INTEGER PRIMARY KEY CHECK(id=1),installation TEXT NOT NULL) STRICT; CREATE TABLE operations(run_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,bytes INTEGER NOT NULL,chunks INTEGER NOT NULL,result TEXT,PRIMARY KEY(run_id,operation_id)) STRICT; PRAGMA application_id=${APPLICATION_ID}; PRAGMA user_version=1;`);
        this.#db.prepare('INSERT INTO identity VALUES(1,?)').run(`installation_${randomUUID()}`);
      });
      const installation = this.#db.prepare('SELECT installation FROM identity WHERE id=1').get()?.installation;
      if (typeof installation !== 'string' || !/^installation_[a-f0-9-]{36}$/.test(installation) || this.#db.prepare('PRAGMA quick_check').get()?.quick_check !== 'ok') throw new RunnerError('RAG_LEDGER_INVALID', '검색 실행 기록의 무결성 검사를 통과하지 못했습니다.');
      this.#installation = installation;
    } catch (error) { this.#db.close(); throw error; }
  }
  close(): void { if (!this.#closed) { this.#db.close(); this.#closed = true; } }
  /** runId is a RunStore-issued identity passed by RunnerService, not a field accepted from node input. */
  principal(runId: string): Principal {
    if (!/^run_[a-f0-9-]{36}$/.test(runId)) throw new RunnerError('RAG_RUN_IDENTITY', 'Runner가 발급한 현재 실행 식별자가 필요합니다.');
    return { scope: { tenantId: this.#installation, projectId: runId }, subjectId: `reader_${canonicalDigest({ installation: this.#installation, runId })}` };
  }
  /** Intents and cumulative reservations commit together. Failed/uncertain attempts retain reservations across restart. */
  reserve(runId: string, operationId: string, requestHash: string, kind: 'build' | 'open' | 'search', bytes: number, chunks: number): Operation | null {
    this.principal(runId);
    if (!/^op_[a-f0-9]{64}$/.test(operationId) || !/^[a-f0-9]{64}$/.test(requestHash)) throw new RunnerError('RAG_OPERATION_IDENTITY', '검색 작업 식별자가 올바르지 않습니다.');
    return this.transaction(() => {
      const existing = this.#db.prepare('SELECT request_hash,state,length(CAST(result AS BLOB)) AS size FROM operations WHERE run_id=? AND operation_id=?').get(runId, operationId);
      if (existing) {
        if (existing.request_hash !== requestHash) throw new RunnerError('RAG_OPERATION_CONFLICT', '같은 검색 작업 식별자에 다른 입력을 사용할 수 없습니다.');
        if (existing.state !== 'completed') throw new RunnerError('RAG_RECONCILIATION_REQUIRED', '이 검색 작업은 중단되었거나 실패했습니다. 자동 재실행하지 않습니다.');
        if (Number(existing.size) > 8192) throw new RunnerError('RAG_LEDGER_INVALID', '검색 작업 결과 기록이 올바르지 않습니다.');
        const result = this.#db.prepare('SELECT result FROM operations WHERE run_id=? AND operation_id=?').get(runId, operationId)?.result;
        if (typeof result !== 'string') throw new RunnerError('RAG_LEDGER_INVALID', '검색 작업 결과 기록이 올바르지 않습니다.');
        return { requestHash, status: 'completed', result: parseStrictJson(result) };
      }
      const usage = this.#db.prepare("SELECT COUNT(*) AS operations,COALESCE(SUM(CASE WHEN kind='build' THEN 1 ELSE 0 END),0) AS builds,COALESCE(SUM(bytes),0) AS bytes,COALESCE(SUM(chunks),0) AS chunks FROM operations WHERE run_id=?").get(runId)!;
      if (Number(usage.operations) + 1 > RUN_RAG_LIMITS.operations || Number(usage.builds) + Number(kind === 'build') > RUN_RAG_LIMITS.builds || Number(usage.bytes) + bytes > RUN_RAG_LIMITS.runBytes || Number(usage.chunks) + chunks > RUN_RAG_LIMITS.runChunks) throw new RunnerError('RAG_BUDGET_EXCEEDED', '현재 실행의 색인·검색 작업 또는 원문·청크 한도를 초과했습니다.');
      this.#db.prepare('INSERT INTO operations(run_id,operation_id,request_hash,kind,state,bytes,chunks) VALUES(?,?,?,?,?,?,?)').run(runId, operationId, requestHash, kind, 'pending', bytes, chunks);
      return null;
    });
  }
  complete(runId: string, operationId: string, result: unknown): void {
    const json = JSON.stringify(result);
    if (Buffer.byteLength(json) > 8192) throw new RunnerError('RAG_LEDGER_INVALID', '검색 기록에는 고정 참조만 저장할 수 있습니다.');
    const updated = this.#db.prepare("UPDATE operations SET state='completed',result=? WHERE run_id=? AND operation_id=? AND state='pending'").run(json, runId, operationId);
    if (updated.changes !== 1) throw new RunnerError('RAG_OPERATION_CONFLICT', '검색 작업 상태가 이미 변경되었습니다.');
  }
  fail(runId: string, operationId: string): void { this.#db.prepare("UPDATE operations SET state='failed' WHERE run_id=? AND operation_id=? AND state='pending'").run(runId, operationId); }
  /** Only completed builds can be opened; a cancelled build's already-staged bytes never become a user-supplied back door. */
  ownsIndex(runId: string, ref: IndexRef): boolean {
    const rows = this.#db.prepare("SELECT operation_id,length(CAST(result AS BLOB)) AS size FROM operations WHERE run_id=? AND kind='build' AND state='completed' LIMIT ?").all(runId, RUN_RAG_LIMITS.builds + 1);
    if (rows.length > RUN_RAG_LIMITS.builds || rows.some(row => Number(row.size) > 8192)) throw new RunnerError('RAG_LEDGER_INVALID', '색인 소유 기록이 한도를 초과했습니다.');
    return rows.some(row => { const result = this.#db.prepare('SELECT result FROM operations WHERE run_id=? AND operation_id=?').get(runId, row.operation_id!)?.result; return typeof result === 'string' && canonicalDigest(parseStrictJson(result)) === canonicalDigest(ref); });
  }
  private transaction<T>(action: () => T): T {
    this.#db.exec('BEGIN IMMEDIATE');
    try { const result = action(); this.#db.exec('COMMIT'); return result; } catch (error) { this.#db.exec('ROLLBACK'); throw error; }
  }
}
